export type MarkdownHeading = {
  /** The heading level, from 1 (top level) to 6. */
  depth: number
  /** The plain-text content of the heading, with all inline formatting removed. */
  value: string
}

/** Matches an ATX heading line: up to three leading spaces, 1–6 hashes, then a space or the end of the line. */
const ATX_HEADING = /^ {0,3}(#{1,6})(?:[ \t]+(.*))?$/

/** Matches a fenced code block delimiter (three or more backticks or tildes). */
const CODE_FENCE = /^ {0,3}(`{3,}|~{3,})/

/** Matches a trailing closing sequence of hashes on an ATX heading (e.g. `## Title ##`). */
const CLOSING_HASHES = /[ \t]+#+[ \t]*$/

/** Matches a setext underline made entirely of `=` characters (depth 1). */
const SETEXT_EQUALS = /^ {0,3}=+[ \t]*$/

/** Matches a setext underline made entirely of `-` characters (depth 2). */
const SETEXT_DASHES = /^ {0,3}-+[ \t]*$/

/**
 * Removes inline Markdown and HTML formatting from a heading, leaving only the readable text.
 *
 * Images and links are reduced to their alt/link text, inline code and emphasis markers are
 * dropped while keeping their content, and HTML tags are removed entirely.
 */
const stripInlineFormatting = (input: string): string =>
  input
    // Images: keep the alt text (must run before links because of the shared bracket syntax)
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: keep the link text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Inline code: keep the code, drop the backticks
    .replace(/`([^`]+)`/g, '$1')
    // Bold: **text** and __text__
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    // Strikethrough: ~~text~~
    .replace(/~~([^~]+)~~/g, '$1')
    // Italic: *text* and _text_
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    // HTML tags
    .replace(/<[^>]+>/g, '')
    .trim()

/**
 * Parses a Markdown string and returns its headings in document order.
 *
 * Supports both ATX headings (`# Title`) and setext headings (a line of text underlined with
 * `=` or `-`). Content inside fenced and indented code blocks is ignored so that hash characters
 * there are not mistaken for headings. All inline formatting is stripped from the returned value.
 *
 * @param markdown - The Markdown string to parse
 * @returns An array of headings, each with a `depth` (1–6) and a plain-text `value`
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n\nIntro\n\nInstallation\n------------')
 * // Returns:
 * // [
 * //   { depth: 1, value: 'Getting Started' },
 * //   { depth: 2, value: 'Installation' },
 * // ]
 */
export const getMarkdownHeadings = (markdown: string): MarkdownHeading[] => {
  if (!markdown) {
    return []
  }

  // Normalize Windows (CRLF) and old-style Mac (CR) line endings.
  const lines = markdown.replace(/\r\n?/g, '\n').split('\n')

  const headings: MarkdownHeading[] = []

  // Track whether we are currently inside a fenced code block and which marker opened it.
  let insideFence = false
  let fenceMarker = ''

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]

    // Toggle fenced code blocks. The closing fence must use the same marker character.
    const fenceMatch = line.match(CODE_FENCE)
    if (fenceMatch) {
      const marker = fenceMatch[1][0]

      if (!insideFence) {
        insideFence = true
        fenceMarker = marker
      } else if (marker === fenceMarker) {
        insideFence = false
        fenceMarker = ''
      }

      continue
    }

    // Everything inside a fenced code block is content, never a heading.
    if (insideFence) {
      continue
    }

    // ATX headings: `# Title` through `###### Title`, with optional closing hashes.
    const atxMatch = line.match(ATX_HEADING)
    if (atxMatch) {
      const depth = atxMatch[1].length
      const raw = (atxMatch[2] ?? '').replace(CLOSING_HASHES, '')
      const value = stripInlineFormatting(raw)

      if (value) {
        headings.push({ depth, value })
      }

      continue
    }

    // Setext headings: a line of text immediately underlined with `=` (depth 1) or `-` (depth 2).
    const underline = lines[index + 1]
    if (underline !== undefined) {
      const isEquals = SETEXT_EQUALS.test(underline)
      const isDashes = SETEXT_DASHES.test(underline)

      // The text line must be a real paragraph line: not blank and not an indented code block.
      const isTextLine = line.trim() !== '' && !/^ {4,}/.test(line)

      if (isTextLine && (isEquals || isDashes)) {
        const value = stripInlineFormatting(line.trim())

        if (value) {
          headings.push({ depth: isEquals ? 1 : 2, value })
        }

        // Skip the underline so it is not reconsidered on the next iteration.
        index++
        continue
      }
    }
  }

  return headings
}
